import org.telegram.messenger.music.SoundCloudPublic;import java.util.*;
public class SoundCloudUnifiedSearchProbe{static String key(Object o){if(o instanceof SoundCloudPublic.Track)return "t"+((SoundCloudPublic.Track)o).id;if(o instanceof SoundCloudPublic.Playlist)return "p"+((SoundCloudPublic.Playlist)o).id;return "a"+((SoundCloudPublic.Artist)o).id;}public static void main(String[] args)throws Exception{SoundCloudPublic.CatalogPage a=SoundCloudPublic.catalog("/search","lofi",null);if(a.items.isEmpty()||a.next==null)throw new AssertionError("Empty search/cursor");SoundCloudPublic.CatalogPage b=SoundCloudPublic.catalog("/search","lofi",a.next);Set<String> keys=new HashSet<>();for(Object x:a.items)keys.add(key(x));int first=keys.size();for(Object x:b.items)keys.add(key(x));if(keys.size()<=first)throw new AssertionError("Pagination did not advance");System.out.println("Live unified search passed: tracks="+a.tracks.size()+", playlists="+a.playlists.size()+", artists="+a.artists.size()+", page2="+b.items.size()+", unique="+keys.size());}}
